export const MAX_FAILED_ATTEMPTS=2;
const blankCourse=c=>({read:[],lesson:0,answers:Array(c.questions.length).fill(null),submitted:false,best:0,attempts:0,failedAttempts:0,question:0,testStartedAt:null,testExpired:false,records:[]});
export const fresh=()=>({version:4,active:'teamwork',courseStates:Object.fromEntries(courses.map(c=>[c.id,blankCourse(c)]))});
const cleanCourse=(raw,c)=>{
 const s=blankCourse(c),source=raw||{};
 s.read=[...new Set((Array.isArray(source.read)?source.read:[]).filter(x=>Number.isInteger(x)&&x>=0&&x<c.lessons.length))].sort((a,b)=>a-b);
 const firstUnread=c.lessons.findIndex((_,i)=>!s.read.includes(i));
 s.lesson=Number.isInteger(source.lesson)?Math.max(0,Math.min(firstUnread<0?c.lessons.length-1:firstUnread,source.lesson)):0;
 s.answers=c.questions.map((q,i)=>Number.isInteger(source.answers?.[i])&&source.answers[i]>=0&&source.answers[i]<q.options.length?source.answers[i]:null);
 s.submitted=source.submitted===true&&s.read.length===c.lessons.length;
 s.best=Number.isInteger(source.best)?Math.max(0,Math.min(c.questions.length,source.best)):0;
 s.attempts=Number.isInteger(source.attempts)?Math.max(0,source.attempts):0;
 s.failedAttempts=Number.isInteger(source.failedAttempts)?Math.max(0,Math.min(MAX_FAILED_ATTEMPTS,source.failedAttempts)):0;
 s.question=Number.isInteger(source.question)?Math.max(0,Math.min(c.questions.length-1,source.question)):0;
 s.testStartedAt=Number.isFinite(source.testStartedAt)?source.testStartedAt:null;s.testExpired=source.testExpired===true;
 s.records=Array.isArray(source.records)?source.records.filter(r=>r&&Number.isInteger(r.score)&&r.score>=0&&r.score<=c.questions.length&&typeof r.passed==='boolean'&&Number.isFinite(r.completedAt)).map(r=>({score:r.score,passed:r.passed,completedAt:r.completedAt,expired:r.expired===true,attempt:Number.isInteger(r.attempt)?Math.max(1,r.attempt):1})):[];
 return s;
};
export function normalise(raw){
 const s=fresh();if(!raw)return s;
 if([2,3].includes(raw.version)){s.courseStates.teamwork=cleanCourse(raw,courses[0]);return s;}
 if(raw.version!==4)return s;
 s.active=courses.some(c=>c.id===raw.active)?raw.active:'teamwork';
 for(const c of courses)s.courseStates[c.id]=cleanCourse(raw.courseStates?.[c.id],c);
 return s;
}
export const score=(answers,c=courses[0])=>c.questions.reduce((n,q,i)=>n+(answers[i]===q.answer?1:0),0);
export const completed=(s,c=courses[0])=>s.read.length===c.lessons.length&&s.best>=c.passMark;
export const certificateEligible=state=>courses.every(c=>completed(state.courseStates[c.id],c));
